discrete OpticalSignalAcquisitionSystem
port:
    event input real ExposureStartCommand;
    event output real ReadoutSignal;
state:
    initial state WaitForExposureCommand
        when entry() then
            statehold(0);
        end;
        when receive(ExposureStartCommand) then
            transition(ExposureInProgress);
        end;
    end;

    state ExposureInProgress
        when entry() then
            statehold(10);
        end;
        when timeover() then
            transition(ExposureCompleted);
            out
                send(ReadoutSignal, 1);
        end;
    end;

    state ExposureCompleted
        when entry() then
            statehold(0);
        end;
        when receive(ExposureStartCommand) then
            transition(WaitForExposureCommand);
        end;
    end;
end;
end;

discrete ElectricalSignalConversionSystem
port:
    event input real ReadoutSignal;
    event output real ConvertedData;
state:
    initial state WaitForReadoutSignal
        when entry() then
            statehold(0);
        end;
        when receive(ReadoutSignal) then
            transition(ReadingAndConverting);
        end;
    end;

    state ReadingAndConverting
        when entry() then
            statehold(5);
        end;
        when timeover() then
            transition(ConversionCompleted);
            out
                send(ConvertedData, 1);
        end;
    end;

    state ConversionCompleted
        when entry() then
            statehold(0);
        end;
        when receive(ReadoutSignal) then
            transition(ReadingAndConverting);
        end;
    end;
end;
end;

discrete DataProcessingAndTransmissionSystem
port:
    event input real ConvertedData;         // Converted telecommunications data
event input real TargetDeviceReady;     // Target equipment ready to receive data.
event output real DataTransmissionComplete;  // Data transfer complete.
state:
    initial state WaitForDataInput
        when entry() then
            statehold(0);
        end;
        when receive(ConvertedData) then
            transition(DataProcessing);
        end;
    end;

    state DataProcessing
        when entry() then
            statehold(3);  // Assumptions of data processing time3sec
end;
        when timeover() then
            transition(DataReadyForTransmission);
        end;
    end;

    state DataReadyForTransmission
        when entry() then
            statehold(0);
        end;
        when receive(TargetDeviceReady) then
            transition(DataTransmitting);
        end;
    end;

    state DataTransmitting
        when entry() then
            statehold(2);  // Assuming data transfer time is2sec
end;
        when timeover() then
            transition(TransmissionComplete);
            out
                send(DataTransmissionComplete, 1);
        end;
    end;

    state TransmissionComplete
        when entry() then
            statehold(0);
        end;
        when receive(ConvertedData) then
            transition(WaitForDataInput);
        end;
    end;
end;
end;

couple ImageSensorSystem
